ALTER TABLE "site_settings" ADD COLUMN     "commission_intro" TEXT NOT NULL DEFAULT 'Tell us what to make, how big and in which glaze. We sketch it, throw it and fire it, and it reaches you in about ten days.',
ADD COLUMN     "commission_steps" JSONB NOT NULL DEFAULT '[{"title":"You send the brief","detail":"The piece, the size, the glaze and the words, in the form below."},{"title":"We sketch it, within two days","detail":"A drawing and a price come back by email. Nothing is owed yet."},{"title":"It is thrown","detail":"One sitting at the wheel, then a week drying to leather-hard."},{"title":"It is glazed and fired","detail":"Bisque, then the glaze firing at 1225°C. The kiln decides the rest."},{"title":"It ships, about ten days in","detail":"Packed in straw and paper, tracked, to the address you give us."}]';

